<script setup lang="ts">
import {ref,watch,computed} from 'vue';import axios from 'axios';import {RouterLink} from 'vue-router';
const props=defineProps<{kind:'SELL'|'WANTED';keyword?:string}>();
const items=ref<any[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref('');const pages=computed(()=>Math.ceil(total.value/3));let snapshot=0,seq=0,start=0,startY=0,lastWheel=0,lastSwipe=0;
async function load(n=1){const s=++seq;busy.value=true;error.value='';try{const {data}=await axios.get('/api/products',{params:{kind:props.kind,keyword:props.keyword||'',page:n,size:3,snapshot}});if(s!==seq)return;snapshot=data.snapshot;items.value=data.items;total.value=data.total;page.value=n;}catch{error.value='加载失败，请重试';}finally{if(s===seq)busy.value=false;}}
function move(n:number){if(!busy.value&&n>=1&&n<=pages.value)load(n);}
function pointerEnd(e:PointerEvent){const diff=e.clientX-start;if(Math.abs(diff)>55&&Math.abs(e.clientY-startY)<Math.abs(diff)){lastSwipe=Date.now();move(page.value+(diff<0?1:-1));}}
function suppressSwipeClick(e:MouseEvent){if(Date.now()-lastSwipe<400){e.preventDefault();e.stopPropagation();}}

function wheel(e:WheelEvent){if(Math.abs(e.deltaX)>25&&Date.now()-lastWheel>600){lastWheel=Date.now();move(page.value+(e.deltaX>0?1:-1));}}
watch(()=>[props.kind,props.keyword],()=>{snapshot=0;load();},{immediate:true});
</script><template><section class="listing-section"><header><div><p>{{kind==='SELL'?'CAMPUS FINDS':'CAMPUS WISHES'}}</p><h2>{{kind==='SELL'?'同学们在卖':'同学们想要'}}</h2></div><span>{{total}} 件 · 滑动发现更多</span></header><div class="slider" @pointerdown="start=$event.clientX;startY=$event.clientY" @pointerup="pointerEnd" @click.capture="suppressSwipeClick" @dragstart.prevent @wheel="wheel"><p v-if="error" role="alert">{{error}} <button @click="load(page)">重试</button></p><p v-else-if="!items.length&&!busy">暂无{{kind==='SELL'?'出售':'求购'}}信息。</p><div v-else class="listing-grid" :class="{loading:busy}" :key="page"><article v-for="p in items" :key="p.id"><RouterLink :to="'/market/'+p.id"><img class="photo" :src="p.imageUrl" :alt="p.title"><div class="copy"><small>{{kind==='SELL'?'闲置转让':'求购 / 感兴趣'}}</small><h3>{{p.title}}</h3><span>{{p.location||'地点待补充'}}</span><strong>{{kind==='WANTED'?'预算 ':''}}¥ {{Number(p.price).toFixed(2)}}</strong></div></RouterLink><RouterLink v-if="p.ownerId" class="seller" :to="'/people/'+p.ownerId"><img :src="'/api/conversations/avatars/'+p.ownerId" alt="发布者头像">{{p.ownerName}} ↗</RouterLink></article></div><p v-if="busy" class="loading-note" role="status">正在加载…</p></div><div v-if="pages>1" class="progress"><button :disabled="page<=1||busy" @click="move(page-1)" aria-label="上一组">←</button><div class="dots"><button v-for="n in pages" :key="n" :class="{active:page===n}" :aria-label="'第'+n+'组'" :aria-current="page===n?'page':undefined" :disabled="busy" @click="move(n)"></button></div><button :disabled="page>=pages||busy" @click="move(page+1)" aria-label="下一组">→</button></div></section></template><style scoped>.listing-section{margin:35px 0 55px}.listing-section>header{display:flex;justify-content:space-between;align-items:center;gap:20px}.listing-section header p{font-size:10px;letter-spacing:2px;color:#96764e}h2{font-size:25px;margin:12px 0 25px}.listing-section header>span{font-size:11px;color:#8b8f7f}.slider{position:relative;touch-action:pan-y;min-height:100px}.listing-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;animation:slide-in .25s}.loading{opacity:.5}article{background:white;border:1px solid #e2e3d8;border-radius:12px;overflow:hidden}a{text-decoration:none;color:inherit}.photo{width:100%;height:210px;object-fit:contain;background:#eeeee6;padding:15px}.copy{padding:20px}.copy small{font-size:10px;color:#98784f}.copy h3{font-size:18px;overflow-wrap:anywhere}.copy>span{display:block;font-size:11px;color:#88907e;margin-bottom:18px}.copy strong{color:#a25438;font-size:21px}.seller{display:flex;gap:9px;align-items:center;border-top:1px solid #eeeee5;margin:0 20px;padding:14px 0;font-size:12px}.seller img{width:27px;height:27px;border-radius:50%;object-fit:cover}.progress{display:flex;align-items:center;justify-content:center;gap:22px;margin:25px 0}.progress>button{border:1px solid #dbddce;border-radius:50%;background:white;width:34px;height:34px;color:#304b49;cursor:pointer}.dots{display:flex;gap:8px;max-width:70%;overflow:auto;padding:8px}.dots button{padding:0;border:0;background:#d8d8c9;width:7px;height:7px;min-width:7px;border-radius:50%;cursor:pointer}.dots .active{width:22px;background:#99784b;border-radius:5px}button:disabled{opacity:.4}.loading-note{font-size:12px;color:#8d8069}@keyframes slide-in{from{opacity:.3;transform:translateX(12px)}to{opacity:1;transform:none}}@media(max-width:650px){.listing-grid{gap:9px}.photo{height:110px;padding:6px}.copy{padding:10px}.copy h3{font-size:13px}.copy strong{font-size:15px}.seller{margin:0 8px;font-size:10px;gap:4px}.seller img{width:20px;height:20px}}@media(prefers-reduced-motion:reduce){.listing-grid{animation:none}}</style>
